def transform(grid):
    R, C = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Fill enclosed 0s or hole filling
    # Notice input had a 0 at (5, 4) which became 1
    # Check 4-connected components of 0s not touching boundary
    visited = [[False]*C for _ in range(R)]
    q = []
    for r in range(R):
        for c in range(C):
            if (r == 0 or r == R-1 or c == 0 or c == C-1) and grid[r][c] == 0:
                visited[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.pop(0)
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < R and 0 <= nc < C and not visited[nr][nc] and grid[nr][nc] == 0:
                visited[nr][nc] = True
                q.append((nr, nc))
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 0 and not visited[r][c]:
                out[r][c] = 1
    return out

def transform(grid):
    # Cellular automaton: fill 0 if at least 4 neighbors (orthogonal) are 1
    R, C = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(1, R-1):
        for c in range(1, C-1):
            if grid[r][c] == 0:
                neighbors = [grid[r+dr][c+dc] for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]]
                if sum(neighbors) == 4:
                    out[r][c] = 1
    return out

def transform(grid):
    # Fill any 0 with at least 5 of 8 neighbors being 1
    R, C = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(1, R-1):
        for c in range(1, C-1):
            if grid[r][c] == 0:
                count = sum(grid[r+dr][c+dc] for dr in [-1,0,1] for dc in [-1,0,1] if (dr, dc) != (0,0))
                if count >= 5:
                    out[r][c] = 1
    return out

def transform(grid):
    # Row and column convex hull: fill 0 if between 1s in both its row and its column
    R, C = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 0:
                has_left = any(grid[r][cc] == 1 for cc in range(c))
                has_right = any(grid[r][cc] == 1 for cc in range(c+1, C))
                has_up = any(grid[rr][c] == 1 for rr in range(r))
                has_down = any(grid[rr][c] == 1 for rr in range(r+1, R))
                if has_left and has_right and has_up and has_down:
                    out[r][c] = 1
    return out

def transform(grid):
    # Make shape 4-way symmetric around the center of mass
    coords = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == 1]
    cr = round(sum(r for r, c in coords) / len(coords))
    cc = round(sum(c for r, c in coords) / len(coords))
    out = [row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            dr, dc = abs(r - cr), abs(c - cc)
